CREATE TABLE IF NOT EXISTS public.td_station_addresses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name_zh text NOT NULL CHECK (length(trim(name_zh)) BETWEEN 1 AND 120),name_my text NOT NULL DEFAULT '',address_zh text NOT NULL DEFAULT '',address_my text NOT NULL DEFAULT '',phones text NOT NULL DEFAULT '',map_url text NOT NULL DEFAULT '',is_active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now()); ALTER TABLE public.td_station_addresses ENABLE ROW LEVEL SECURITY; GRANT SELECT,INSERT,UPDATE ON public.td_station_addresses TO authenticated; CREATE POLICY station_read_active_members ON public.td_station_addresses FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.td_members m WHERE m.id=(SELECT auth.uid()) AND m.active=true)); CREATE POLICY station_insert_active_members ON public.td_station_addresses FOR INSERT TO authenticated WITH CHECK (EXISTS (SELECT 1 FROM public.td_members m WHERE m.id=(SELECT auth.uid()) AND m.active=true)); CREATE POLICY station_update_active_members ON public.td_station_addresses FOR UPDATE TO authenticated USING (EXISTS (SELECT 1 FROM public.td_members m WHERE m.id=(SELECT auth.uid()) AND m.active=true)) WITH CHECK (EXISTS (SELECT 1 FROM public.td_members m WHERE m.id=(SELECT auth.uid()) AND m.active=true));